"    // Switch songs
    function switchSong(songId) {
        if (songId === currentSongId) return;

        stopPractice();
        currentSongId = songId;

        // Update tabs active state
        const tabBtns = document.querySelectorAll(".tab-btn");
        tabBtns.forEach(btn => btn.classList.remove("active"));
        event.target.classList.add("active");

        // Update header details
        document.getElementById("song-title").innerText = songs[songId].title;
        document.getElementById("song-desc").innerText = songs[songId].desc;

        // Update video links and texts
        document.getElementById("btn-video-link").href = videoUrls[songId];
        document.getElementById("video-link-text").innerText = videoTexts[songId];
        document.getElementById("btn-yt-search-link").href = ytSearchUrls[songId];
        document.getElementById("yt-search-text").innerText = ytSearchTexts[songId];

        renderLyrics(songId);
    }"

